package com.mitcampus.ams.dto;
import jakarta.validation.constraints.*;import java.time.*;import java.util.*;
public final class Requests { private Requests(){} public record Login(@Email String email,@NotBlank String password,@Pattern(regexp="student|official") String role){} public record StudentRegistration(@NotBlank String name,@NotBlank String registerNumber,@NotBlank String department,@NotBlank String year,@Email String email,@NotBlank String password,@NotBlank String confirmPassword,String contactNumber){} public record OfficialRegistration(@NotBlank String name,@NotBlank String employeeId,@Email String email,@NotBlank String password,@NotBlank String confirmPassword,String contactNumber,@NotBlank String designation,@NotBlank String department){} public record AppointmentRequest(@NotNull Long studentId,@NotNull Long officialId,@NotBlank String purpose,String description,@NotNull LocalDate requestedDate,@NotNull LocalTime preferredTime){} public record Decision(@NotNull LocalDate allocatedDate,@NotNull LocalTime allocatedTime,String remarks,Long officialId){} public record Reject(String remarks,Long officialId){} public record AvailabilityItem(String day,LocalTime startTime,LocalTime endTime,boolean isAvailable){} public record AvailabilitySave(List<AvailabilityItem> items){} }
